$ErrorActionPreference = 'Continue'; $site = (Resolve-Path .venv\Lib\site-packages -ErrorAction Stop).Path; $env:PYTHONPATH = "$site;$site\win32;$site\win32\lib"; $env:PATH = "$site\pywin32_system32;$env:PATH"; $python = (py -3.14 -c "import sys; print(sys.executable)").Trim(); if ($LASTEXITCODE -ne 0) { throw 'Cannot locate Python 3.14.' }; & $python -m PyInstaller --noconfirm --clean --distpath dist --workpath "build\pyinstaller" "packaging\Kidsroom.spec"; if ($LASTEXITCODE -ne 0) { throw 'PyInstaller build failed.' }; & $python "scripts\bundle-notices.py" "dist\Kidsroom"; if ($LASTEXITCODE -ne 0) { throw 'Could not collect dependency notices.' }; Copy-Item -LiteralPath "README.md" -Destination "dist\Kidsroom" -Force -ErrorAction Stop; Copy-Item -LiteralPath "packaging\PORTABLE.txt" -Destination "dist\Kidsroom\BAT-DAU.txt" -Force -ErrorAction Stop; Copy-Item -LiteralPath "scripts\install-bundled-service.ps1" -Destination "dist\Kidsroom\Install-Service.ps1" -Force -ErrorAction Stop; $version = (& $python -c "import pathlib,tomllib; print(tomllib.loads(pathlib.Path('pyproject.toml').read_text(encoding='utf-8'))['project']['version'])").Trim(); if ($LASTEXITCODE -ne 0) { throw 'Cannot read package version.' }; $archive = "dist\Kidsroom-$version-Windows-x64.zip"; Compress-Archive -LiteralPath "dist\Kidsroom" -DestinationPath $archive -Force -ErrorAction Stop; Write-Host "Executable: $(Join-Path (Resolve-Path 'dist\Kidsroom').Path 'Kidsroom.exe')"; Write-Host "Portable ZIP: $(Join-Path (Resolve-Path 'dist').Path "Kidsroom-$version-Windows-x64.zip")"